CREATE TABLE "notifications"("id" BIGSERIAL PRIMARY KEY,"public_id" UUID NOT NULL UNIQUE,"tenant_id" BIGINT NOT NULL,"user_id" BIGINT NOT NULL,"topic" TEXT NOT NULL,"title" TEXT NOT NULL,"body" TEXT NOT NULL,"action_url" TEXT,"read_at" TIMESTAMPTZ(6),"created_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY("tenant_id") REFERENCES "tenants"("id") ON DELETE CASCADE,FOREIGN KEY("user_id") REFERENCES "users"("id") ON DELETE CASCADE);CREATE INDEX "notifications_tenant_id_user_id_read_at_created_at_idx" ON "notifications"("tenant_id","user_id","read_at","created_at");
CREATE TABLE "email_templates"("id" BIGSERIAL PRIMARY KEY,"public_id" UUID NOT NULL UNIQUE,"tenant_id" BIGINT NOT NULL,"code" TEXT NOT NULL,"subject" TEXT NOT NULL,"html_body" TEXT NOT NULL,"text_body" TEXT NOT NULL,"version" INTEGER NOT NULL,"active" BOOLEAN NOT NULL DEFAULT true,"created_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY("tenant_id") REFERENCES "tenants"("id") ON DELETE CASCADE);CREATE UNIQUE INDEX "email_templates_tenant_id_code_version_key" ON "email_templates"("tenant_id","code","version");CREATE INDEX "email_templates_tenant_id_code_active_idx" ON "email_templates"("tenant_id","code","active");
